CREATE OR REPLACE FUNCTION public.eco_commit_card(_participant uuid,_versions jsonb,_snapshot jsonb,_rules jsonb,_template uuid,_eligible boolean,_actor uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE current_versions jsonb; oldcard public.eco_cards; newcard public.eco_cards; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; PERFORM 1 FROM eco_participants WHERE id=_participant FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Participant not found'; END IF; SELECT coalesce(jsonb_object_agg(activity_id::text,version),'{}'::jsonb) INTO current_versions FROM eco_contribution_snapshots WHERE participant_id=_participant; IF current_versions<>_versions THEN RAISE EXCEPTION 'Contributions changed; retry card reconciliation'; END IF; SELECT * INTO oldcard FROM eco_cards WHERE participant_id=_participant AND status IN ('generated','under_review') ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF _eligible AND _template IS NULL THEN RETURN jsonb_build_object('status','template_pending'); END IF; IF _eligible AND oldcard.id IS NOT NULL AND oldcard.snapshot=_snapshot AND oldcard.rules_snapshot=_rules THEN UPDATE eco_cards SET status='generated' WHERE id=oldcard.id; RETURN jsonb_build_object('status','generated','cardNumber',oldcard.card_number); END IF; IF oldcard.id IS NOT NULL THEN UPDATE eco_cards SET status=CASE WHEN _eligible THEN 'superseded' ELSE 'revoked' END WHERE id=oldcard.id; INSERT INTO eco_card_events(card_id,event,actor_id) VALUES(oldcard.id,CASE WHEN _eligible THEN 'superseded' ELSE 'revoked' END,_actor); END IF; IF NOT _eligible THEN RETURN jsonb_build_object('status','not_eligible'); END IF; INSERT INTO eco_cards(participant_id,template_id,snapshot,rules_snapshot) VALUES(_participant,_template,_snapshot,_rules) RETURNING * INTO newcard; INSERT INTO eco_card_events(card_id,event,actor_id) VALUES(newcard.id,'generated',_actor); RETURN jsonb_build_object('status','generated','cardNumber',newcard.card_number); END $$; REVOKE ALL ON FUNCTION public.eco_commit_card(uuid,jsonb,jsonb,jsonb,uuid,boolean,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.eco_commit_card(uuid,jsonb,jsonb,jsonb,uuid,boolean,uuid) TO service_role;